import itertools
n=5
sol=[]
for p in itertools.permutations(range(n)):
    if p[2]!=3: continue
    ok=True
    for d in range(1,n):
        diffs=[p[i+d]-p[i] for i in range(n-d)]
        if len(diffs)!=len(set(diffs)):
            ok=False; break
    if ok:
        sol.append(p)
print(len(sol), sol[:20])
